https://app.powerbi.com/view?r=eyJrIjoiNjk4NmRmZjctMzg5Yi00OTQxLTg2ZjgtNTc2NWUyN2I2ZTRjIiwidCI6IjEwNmQ2ZDMyLTU2ODktNGMwZi1hNTdkLTI2MzFmMWZkMWYyOCIsImMiOjl9","source_file":"feder-aragon-2021-2027-20261001.json","source_updated":"2026-10-01"}],"match_method":"","feder_cost_reconciled_to_grant":null,"scope_note":"El coste de la operación FEDER no es la inversión subvencionable del proyecto. Las actuaciones de otros años son antecedentes de la empresa, no el proyecto de esta solicitud.","identity_sources":[]},"province":null},{"import_key":"d23ef66f3c7abd41513e464c","enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[{"operation_code":"D2022156","year":2022,"line":"IDIS-REACT","beneficiary":"OSWALDO TRIGO GUILLO","feder_beneficiary_id":"ES51IS14","operation_name":"OSWALDO TRIGO GUILLO","description":"El proyecto ha consistido en la implantación de un sistema digital que supone un cambio en la forma de trabajar y de gestionar la información. Se ha digitalizado el puesto del operario de máquina. Esto se ha realizado asignando un puesto de ordenador PC fijo junto a cada máquina en la zona de taller con conexión a intranet de la empresa y a internet. De esta manera el operario de máquina puede diseñar piezas y programar máquinas usando el ordenador. Esto permite la fabricación usando software colaborativo basado en la nube. Además puede consultar en formato electrónico los planos, las ordenes de fabricación, los parámetros, etc. Esto se lleva a cabo con más eficacia ya eu el ordenador está junto a la máquina. En la oficina se ha instalado un ordenador PC que hace la función de servidor para el resto de ordenadores y que es utilizado también para las tareas administrativas. Se ha instalado un sistema de almacenamiento NAS para poder gestionar y archivar la información de la empresa de manera eficiente y segura. El proyecto ha constado de cuatro etapas. 1. Trabajos de cableado eléctrico y de red. 2. Adquisición y colocación de mobiliario industrial de puestos de trabajo de taller. 3. Instalación de los equipos informáticos. 4. Instalación software de gestión.","start_date":"01/02/2021","end_date":"31/08/2022","feder_operation_cost":5519.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Utebo","municipality_code":"50272","intervention":"004 Inversión productiva relativas a la cooperación entre grandes empresas y PYME para desarrollar productos y servicios en tecnologías de la información y las comunicaciones (TIC), comercio electrónico y mayor demanda de TIC.","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=665","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":665,"source_updated":"2025-05-29"}],"related_company_operations":[],"match_method":"beneficiario exacto normalizado + anualidad + línea + importe conciliado (tolerancia 1 €)","feder_cost_reconciled_to_grant":true,"scope_note":"El coste de la operación FEDER no es la inversión subvencionable del proyecto. Las actuaciones de otros años son antecedentes de la empresa, no el proyecto de esta solicitud.","identity_sources":[]},"province":"Zaragoza"},{"import_key":"29b2a12af56d9e869c99bcb0","enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[],"related_company_operations":[{"operation_code":"201969","year":2019,"line":"TDI-FEDER (antecedente)","beneficiary":"OSCATECH MICROINYECCION S.L.","feder_beneficiary_id":"ES59C775","operation_name":"OSCATECH MICROINYECCION S.L.","description":"\"Unidad autónoma de producción con conectividad 4.0 cuyo núcleo es una maquina de micro inyección de precisión robot izada para poder producir componentes plásticos para aplicaciones de mecatronica. la maquina esta plenamente integrada con todos los equipos periféricos y los pilota desde la unidad de control\"","start_date":"01/10/2018","end_date":"30/09/2019","feder_operation_cost":142503.0,"eu_cofinancing_percent":50.0,"province":"Huesca","municipality":"Hu