ions":[{"operation_code":"D2022101","year":2022,"line":"IDIS-REACT","beneficiary":"LUEZAR ECO, S.L.","feder_beneficiary_id":"ES51IJ66","operation_name":"LUEZAR ECO, S.L.","description":"El objetivo del proyecto es poder aumentar la capacidad productiva. Actualmente, no es posible llegar a la demanda que tiene la empresa, principalmente para el cliente más importante que es Schindler. Habitualmente LUEZAR ECO depende de un proveedor externo que realiza trabajos de soldadura y en ocasiones hay problemas con los plazos de entrega, es por esto que se ha visto la necesidad de incorporar un robot de soldadura para poder abarcar gran parte de las necesidades de nuestro producto, aunque se siga contando con los proveedores externos.","start_date":"01/02/2021","end_date":"31/08/2022","feder_operation_cost":64410.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Zaragoza","municipality_code":"50297","intervention":"004 Inversión productiva relativas a la cooperación entre grandes empresas y PYME para desarrollar productos y servicios en tecnologías de la información y las comunicaciones (TIC), comercio electrónico y mayor demanda de TIC.","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=623","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":623,"source_updated":"2025-05-29"}],"related_company_operations":[{"operation_code":"2022069","year":2022,"line":"TDI-FEDER (antecedente)","beneficiary":"LUEZAR ECO, S.L.","feder_beneficiary_id":"ES51IJ66","operation_name":"LUEZAR ECO S.L.","description":"\"En la situación económica en la que nos encontramos acentuado por la pandemia provocada por la COVID, las empresas, cada vez más, buscan reducir costes, aumentar la calidad de sus productos y diferenciarse de sus competidores, en definitiva, ser más competitivos. En esta coyuntura, las nuevas tecnologías y la digitalización ofrecen la manera más viable de responder a estas necesidades. El proyecto incluye varias actuaciones como son la adquisicion de un robot de soldadura, la implantación de un ERP y un diagnóstico de digitalización.\"","start_date":"01/01/2021","end_date":"31/12/2021","feder_operation_cost":57800.0,"eu_cofinancing_percent":50.0,"province":"Zaragoza","municipality":"Zaragoza","municipality_code":"50297","intervention":"001 Inversión productiva genérica en pequeñas y medianas –empresas («PYME»)","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=383","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":383,"source_updated":"2025-05-29"}],"match_method":"beneficiario exacto normalizado + anualidad + línea + importe conciliado (tolerancia 1 €)","feder_cost_reconciled_to_grant":true,"scope_note":"El coste de la operación FEDER no es la inversión subvencionable del proyecto. Las actuaciones de otros años son antecedentes de la empresa, no el proyecto de esta solicitud.","identity_sources":[]},"province":"Zaragoza"},{"import_key":"34560de2c598d68e1244bec2","enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[{"operation_code":"D2022097","year":2022,"line":"IDIS-REACT","beneficiary":"LA ZARAGOZANA, S.A.","feder_beneficiary_id":"ES51IS67","operation_name":"LA ZARAGOZANA, S.A.","description":"Objetivo principal: digitalizacion y mejora de la sostenibilidad medioambiental mediante control digital de equipos productivos, recuperación de residuos del proceso productivo, desarrollo de un nuevo producto de pack sostenible.","start_date":"01/02/2021","end_date":"31/08/2022","feder_operation_cost":15459.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Zaragoza","municipality_code":"50297","intervention":"004 Inversión productiva relativas a la cooperación entre grandes empresas y PYME para desarrollar productos y servicios en tecnologías de la información y las comunicaciones (TIC), comercio electrónico y mayor demanda de TI