enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[{"operation_code":"D2022151","year":2022,"line":"IDIS-REACT","beneficiary":"THE KEG COMPANY S.L.","feder_beneficiary_id":"ES51IS65","operation_name":"THE KEG COMPANY S.L.","description":"El obtejo de la presenta solicitud, nace con el objetivo de realizar la transformación digital de los procesos de la planta de TKC sita en la provincia de Zaragoza, de forma que se permita un mayor control y de los productos fabricados, y en consecuencia la reducción del impacto medioambiental derivado de su proceso productivo. Frente al escenario empresarial actual, globalizado y sumamente competitivo, tener una ventaja competitiva es crucial. Este factor diferencial permite a una compañia sobresalir en el mercado y así obtener mejores resultados. En este sentido, TKC, motivada por su deseo de posicionarse como empresa referente en el sector, ha analizado sus procesos y ha definido un Plan de Acción. En este Plan, se ha determinado que las dos grandes áreas en las que se debe actuar son la Digitalización de sus procesos y la Sostenibilidad medioambiental de su actividad industrial.","start_date":"01/02/2021","end_date":"31/08/2022","feder_operation_cost":73025.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Figueruelas","municipality_code":"50107","intervention":"004 Inversión productiva relativas a la cooperación entre grandes empresas y PYME para desarrollar productos y servicios en tecnologías de la información y las comunicaciones (TIC), comercio electrónico y mayor demanda de TIC.","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=661","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":661,"source_updated":"2025-05-29"},{"operation_code":"V2022098","year":2022,"line":"IDIS-REACT","beneficiary":"THE KEG COMPANY S.L.","feder_beneficiary_id":"ES51IS65","operation_name":"THE KEG COMPANY S.L.","description"